from datetime import date
from decimal import Decimal, ROUND_HALF_UP, localcontext
import decimal

def day_count_fraction(start, end, convention):
    def _parse(s):
        if not isinstance(s, str):
            raise ValueError
        if len(s) != 10 or s[4] != "-" or s[7] != "-":
            raise ValueError
        ys = s[0:4]
        ms = s[5:7]
        ds = s[8:10]
        if not (ys.isdigit() and ms.isdigit() and ds.isdigit()):
            raise ValueError
        try:
            return date(int(ys), int(ms), int(ds))
        except ValueError:
            raise ValueError
    def _is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def _is_last_feb(dt):
        if dt.month != 2:
            return False
        if _is_leap(dt.year):
            return dt.day == 29
        return dt.day == 28
    sd = _parse(start)
    ed = _parse(end)
    if not isinstance(convention, str):
        raise ValueError
    if convention not in ("30/360_US", "30E/360", "ACT/365F", "ACT/ACT_ISDA"):
        raise ValueError
    if ed < sd:
        raise ValueError
    if ed == sd:
        return Decimal("0.0000000000")
    with localcontext() as ctx:
        ctx.prec = 50
        if convention == "30/360_US":
            d1 = sd.day
            m1 = sd.month
            y1 = sd.year
            d2 = ed.day
            m2 = ed.month
            y2 = ed.year
            s_last = _is_last_feb(sd)
            e_last = _is_last_feb(ed)
            if s_last:
                d1a = 30
            elif d1 == 31:
                d1a = 30
            else:
                d1a = d1
            if e_last:
                if s_last:
                    d2a = 30
                else:
                    d2a = d2
            else:
                if d2 == 31 and d1a >= 30:
                    d2a = 30
                else:
                    d2a = d2
            dc = 360 * (y2 - y1) + 30 * (m2 - m1) + (d2a - d1a)
            unrounded = Decimal(dc) / Decimal(360)
        elif convention == "30E/360":
            d1a = sd.day
            if d1a > 30:
                d1a = 30
            d2a = ed.day
            if d2a > 30:
                d2a = 30
            dc = 360 * (ed.year - sd.year) + 30 * (ed.month - sd.month) + (d2a - d1a)
            unrounded = Decimal(dc) / Decimal(360)
        elif convention == "ACT/365F":
            actual = (ed - sd).days
            unrounded = Decimal(actual) / Decimal(365)
        else:
            actual = (ed - sd).days
            if sd.year == ed.year:
                denom = 366 if _is_leap(sd.year) else 365
                unrounded = Decimal(actual) / Decimal(denom)
            else:
                first_end = date(sd.year + 1, 1, 1)
                first_days = (first_end - sd).days
                first_denom = 366 if _is_leap(sd.year) else 365
                last_start = date(ed.year, 1, 1)
                last_days = (ed - last_start).days
                last_denom = 366 if _is_leap(ed.year) else 365
                middle = ed.year - sd.year - 1
                unrounded = Decimal(first_days) / Decimal(first_denom) + Decimal(middle) + Decimal(last_days) / Decimal(last_denom)
        q = unrounded.quantize(Decimal("0.0000000000"), rounding=ROUND_HALF_UP)
        return q

